        ));

        register_rest_route('feeddash/v1', '/annotations', array(
            'methods' => 'POST',
            'callback' => array($this, 'createAnnotation'),
            'permission_callback' => array($this, 'checkApiAuth'),
        ));

        register_rest_route('feeddash/v1', '/annotations', array(
