            if ($statusFilter === 'pending') {
                $where[] = '(status = %s OR status = %s)';
                $params[] = 'open';
                $params[] = 'in_progress';
            } else {
                $where[] = 'status = %s';
                $params[] = $statusFilter;
            }
        }
        if (!empty($urlFilter)) {
            $where[] = 'page_url = %s';
            $params[] = $urlFilter;
        }

        $whereSql = implode(' AND ', $where);
        $sql = "SELECT * FROM $tableName WHERE $whereSql ORDER BY created_at DESC";
