                    </tr>
                </thead>
                <tbody>
                <?php if (empty($results)): ?>
                    <tr><td colspan="9" style="text-align:center;padding:30px;color:#94a3b8;">No annotations found.</td></tr>
                <?php else: $idx = 0; foreach ($results as $row): $idx++;
